    "question": "In Avery v. Bowden (1855), the charterer told the ship captain at Odessa before loading days expired that he had no cargo and advised him to leave. The captain refused to accept repudiation and remained. Before loading days expired, the Crimean War broke out, making performance illegal. The court held:",
