    "question": "In Kaliaperumal Pillai v. Visalakshmi Achi (AIR 1938 Mad 32), a lady gave gold to a goldsmith to melt and make jewels. Every evening she took the half-made jewels, placed them in a box, locked it, kept the key with herself, and left the box in the goldsmith's premises. The jewels were stolen at night. The court held:",
    "options": [
      "The goldsmith was liable as a bailee",
      "There was no bailment at night because possession was retained by the lady who locked the box and kept the key; the goldsmith was not liable",
      "The goldsmith was liable for conversion",
      "The lady was liable to pay the goldsmith double wages"
    ],
    "answer": 1,
    "answerLetter": "B",
    "explanation": "The Madras High Court held that bailment requires transfer of exclusive possession. Since the lady kept the key and locked the box, possession was not with the goldsmith at night.",
    "optionBreakdown": {
      "A": "Bailment was absent at night due to lack of possession.",
      "B": "Correct. Leading Indian authority: without transfer of exclusive control, there is no bailment.",
      "C": "No conversion occurred as goldsmith did not take or misuse goods.",
      "D": "No double wages award exists in law."
    },
